import express from 'express';
import { DatabaseSync } from 'node:sqlite';
import dotenv from 'dotenv';
import cors from 'cors';
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StreamableHTTPServerTransport } from '@modelcontextprotocol/sdk/server/streamableHttp.js';

dotenv.config();

const app = express();
const PORT = process.env.PORT || <YOUR_NODE_PORT>;
const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET;

if (!WEBHOOK_SECRET) {
  throw new Error('缺少 WEBHOOK_SECRET 环境变量');
}

const db = new DatabaseSync('health_data.sqlite');
db.exec(`
  CREATE TABLE IF NOT EXISTS health_summary (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    summary_text TEXT NOT NULL,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
  )
`);

app.use(cors({
  origin: '*',
  methods: ['GET', 'POST', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'x-token', 'mcp-session-id', 'last-event-id'],
  exposedHeaders: ['mcp-session-id']
}));
app.use(express.json({ limit: '30mb' }));

const METRIC_NAMES = {
  heart_rate: '心率',
  resting_heart_rate: '静息心率',
  heart_rate_variability: '心率变异性(HRV)',
  walking_heart_rate_average: '步行平均心率',
  step_count: '每日步数',
  flights_climbed: '爬楼层数',
  walking_running_distance: '步行+跑步距离',
  running_distance: '跑步距离',
  active_energy: '活动能量(千卡)',
  basal_energy_burned: '静息能量(千卡)',
  apple_exercise_time: '锻炼时长(分钟)',
  apple_stand_time: '站立时长(分钟)',
  apple_stand_hour: '站立达标小时数',
  headphone_audio_exposure: '耳机音量暴露',
  environmental_audio_exposure: '环境噪音水平',
  oxygen_saturation: '血氧饱和度',
  respiratory_rate: '呼吸频率',
  time_in_daylight: '日光暴露时长(分钟)',
  apple_sleeping_wrist_temperature: '睡眠手腕温度'
};

const CUMULATIVE_METRICS = new Set([
  'step_count', 'flights_climbed', 'walking_running_distance',
  'running_distance', 'active_energy', 'basal_energy_burned',
  'apple_exercise_time', 'apple_stand_time', 'apple_stand_hour',
  'time_in_daylight'
]);

const AVERAGING_METRICS = new Set([
  'heart_rate', 'resting_heart_rate', 'heart_rate_variability',
  'walking_heart_rate_average', 'headphone_audio_exposure',
  'environmental_audio_exposure', 'oxygen_saturation',
  'respiratory_rate', 'apple_sleeping_wrist_temperature'
]);

function cleanHealthData(payload) {
  const metrics = payload?.data?.metrics || [];
  const workouts = payload?.data?.workouts || [];

  const sections = {
    sleep: [],
    cardio: [],
    activity: [],
    hearing: [],
    vitals: [],
    workouts: [],
    others: []
  };

  for (const metric of metrics) {
    const name = metric.name;
    const units = metric.units || '';
    const data = metric.data || [];

    if (!data.length) continue;

    const displayName = METRIC_NAMES[name] || name;

    if (name === 'sleep_analysis') {
      data.slice(-7).forEach((item) => {
        const dateStr = (item.date || item.sleepEnd || '').split(' ')[0] || '未知';
        const total = item.totalSleep
          ? Number(item.totalSleep)
          : (item.asleep ? Number(item.asleep) : 0);

        if (total <= 0 && !item.inBed) return;

        const phases = [];
        if (item.deep) phases.push(`深睡 ${Number(item.deep).toFixed(1)}h`);
        if (item.core) phases.push(`核心 ${Number(item.core).toFixed(1)}h`);
        if (item.rem) phases.push(`REM ${Number(item.rem).toFixed(1)}h`);
        if (item.awake) phases.push(`清醒 ${Number(item.awake).toFixed(1)}h`);

        let timeRange = '';
        if (item.sleepStart && item.sleepEnd) {
          const start = item.sleepStart.split(' ')[1]?.substring(0, 5) || '';
          const end = item.sleepEnd.split(' ')[1]?.substring(0, 5) || '';
          if (start && end) timeRange = ` [${start} ~ ${end}]`;
        }

        const phaseText = phases.length ? ` (${phases.join(', ')})` : '';
        sections.sleep.push(`  · ${dateStr}${timeRange}: 睡眠 ${total.toFixed(1)}小时${phaseText}`);
      });
      continue;
    }

    if (CUMULATIVE_METRICS.has(name)) {
      const dayMap = {};

      data.forEach((item) => {
        const day = (item.date || '').split(' ')[0] || '未知';
        const value = Number(item.qty !== undefined ? item.qty : (item.Avg || 0));
        dayMap[day] = (dayMap[day] || 0) + value;
      });

      const daySummary = Object.entries(dayMap)
        .slice(-7)
        .map(([day, value]) => {
          const formatted = name.includes('distance')
            ? value.toFixed(2)
            : Math.round(value);
          return `${day}: ${formatted}`;
        })
        .join(', ');

      sections.activity.push(`- ${displayName}: ${daySummary} ${units}`);
      continue;
    }

    if (AVERAGING_METRICS.has(name)) {
      const isAggregated = data.some((item) => item.Avg !== undefined);
      let average;
      let maximum;
      let minimum;

      if (isAggregated) {
        const averageList = data
          .map((item) => Number(item.Avg))
          .filter((value) => !Number.isNaN(value));

        if (averageList.length > 0) {
          average = (averageList.reduce((a, b) => a + b, 0) / averageList.length).toFixed(1);
        }

        const maxList = data
          .map((item) => Number(item.Max))
          .filter((value) => !Number.isNaN(value));
        const minList = data
          .map((item) => Number(item.Min))
          .filter((value) => !Number.isNaN(value));

        maximum = maxList.length ? Math.max(...maxList).toFixed(0) : null;
        minimum = minList.length ? Math.min(...minList).toFixed(0) : null;
      } else {
        const values = data
          .map((item) => Number(item.qty))
          .filter((value) => !Number.isNaN(value));

        if (values.length > 0) {
          average = (values.reduce((a, b) => a + b, 0) / values.length).toFixed(1);
          maximum = Math.max(...values).toFixed(0);
          minimum = Math.min(...values).toFixed(0);
        }
      }

      if (average !== undefined) {
        let line = `- ${displayName}: 平均 ${average} ${units}`;

        if (maximum && minimum && (name === 'heart_rate' || name.includes('exposure'))) {
          line += ` (最高 ${maximum}, 最低 ${minimum})`;
        }

        if (name.includes('heart') || name === 'heart_rate_variability') {
          sections.cardio.push(line);
        } else if (name.includes('exposure')) {
          sections.hearing.push(line);
        } else {
          sections.vitals.push(line);
        }
      }
      continue;
    }

    const last = data[data.length - 1];
    if (last) {
      const value = last.qty !== undefined
        ? Number(last.qty).toFixed(1)
        : (last.Avg !== undefined ? Number(last.Avg).toFixed(1) : '');

      if (value) sections.others.push(`- ${displayName}: 最近值 ${value} ${units}`);
    }
  }

  if (workouts.length > 0) {
    workouts.slice(-5).forEach((workout) => {
      const type = workout.name || workout.activity || '体能训练';
      const duration = workout.duration
        ? `${(Number(workout.duration) / 60).toFixed(0)}分钟`
        : '';
      const calories = workout.activeEnergy
        ? `${Math.round(workout.activeEnergy)}kcal`
        : '';
      const date = (workout.start || workout.date || '').split(' ')[0];
      sections.workouts.push(`  · ${date} ${type}: ${duration} ${calories}`);
    });
  }

  const report = [];
  report.push(`【Apple Watch 最近 7 天健康体征全景（更新于 ${new Date().toLocaleString('zh-CN')}）】\n`);

  if (sections.sleep.length) {
    report.push(`### 🛌 睡眠分析 (Sleep Analysis)\n${sections.sleep.join('\n')}\n`);
  }
  if (sections.cardio.length) {
    report.push(`### ❤️ 心血管与体能 (Cardio Health)\n${sections.cardio.join('\n')}\n`);
  }
  if (sections.activity.length) {
    report.push(`### 🏃 活动与消耗 (Daily Activity)\n${sections.activity.join('\n')}\n`);
  }
  if (sections.hearing.length) {
    report.push(`### 🎧 听力与环境 (Hearing & Environment)\n${sections.hearing.join('\n')}\n`);
  }
  if (sections.vitals.length) {
    report.push(`### 🫁 呼吸与生理体征 (Vitals)\n${sections.vitals.join('\n')}\n`);
  }
  if (sections.workouts.length) {
    report.push(`### 🏋️ 健身记录 (Workouts)\n${sections.workouts.join('\n')}\n`);
  }
  if (sections.others.length) {
    report.push(`### 📌 其他指标\n${sections.others.join('\n')}\n`);
  }

  return report.join('\n');
}

app.post('/api/health-webhook', (req, res) => {
  const clientToken = req.headers['x-token'] || req.query.token;

  if (!clientToken || clientToken !== WEBHOOK_SECRET) {
    return res.status(401).json({ error: 'Unauthorized: Secret Token 无效' });
  }

  try {
    const summaryText = cleanHealthData(req.body);
    const statement = db.prepare(`
      INSERT INTO health_summary (id, summary_text, updated_at)
      VALUES (1, ?, CURRENT_TIMESTAMP)
      ON CONFLICT(id) DO UPDATE SET
        summary_text = excluded.summary_text,
        updated_at = CURRENT_TIMESTAMP
    `);

    statement.run(summaryText);
    console.log(`[${new Date().toISOString()}] 健康数据已成功入库更新`);
    return res.json({ success: true, message: 'Health summary saved successfully' });
  } catch (error) {
    console.error('写入错误:', error);
    return res.status(500).json({ error: '数据处理或存储失败' });
  }
});

function createMcpServer() {
  const server = new McpServer({
    name: 'apple-watch-mcp-server',
    version: '1.0.0'
  });

  server.tool(
    'get_health_data',
    '获取用户最近7天的 Apple Watch 全量健康数据汇总',
    {},
    async () => {
      const statement = db.prepare(
        'SELECT summary_text, updated_at FROM health_summary WHERE id = 1'
      );
      const row = statement.get();

      if (!row) {
        return {
          content: [
            {
              type: 'text',
              text: '暂无健康数据，请确认是否已完成数据同步。'
            }
          ]
        };
      }

      return {
        content: [
          {
            type: 'text',
            text: `${row.summary_text}\n\n(数据入库时间: ${row.updated_at})`
          }
        ]
      };
    }
  );

  return server;
}

const handleMcp = async (req, res) => {
  try {
    const transport = new StreamableHTTPServerTransport({
      sessionIdGenerator: undefined
    });
    const mcpServer = createMcpServer();

    await mcpServer.connect(transport);
    await transport.handleRequest(req, res, req.body);
  } catch (error) {
    console.error('MCP Transport Error:', error);

    if (!res.headersSent) {
      res.status(500).json({ error: error.message });
    }
  }
};

app.all('/mcp', handleMcp);
app.all('/sse', handleMcp);
app.all('/', handleMcp);

app.listen(PORT, '127.0.0.1', () => {
  console.log(`服务已在 http://127.0.0.1:${PORT} 启动`);
});
